export function getAssetRegistryErrorMessage(code: AssetRegistryError): string {
  if (process.env.NODE_ENV !== "production") {
    return (assetRegistryErrorMessages as Record<AssetRegistryError, string>)[
      code
    ];
  }

  return "Error message not available in production bundles.";
}

export function isAssetRegistryError<
  TProgramErrorCode extends AssetRegistryError,
>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    ASSET_REGISTRY_PROGRAM_ADDRESS,
    code,
  );
}
